import pandas as pd
import sqlite3
import os

def solve(data_dir):
    # Ruta del archivo CSV
    csv_path = os.path.join(data_dir, "clientes_crm.csv")

    # Leer el archivo CSV
    # El archivo tiene un formato donde la columna monto_compras incluye el símbolo "$" y comas para decimales
    df = pd.read_csv(csv_path)

    # Función para limpiar y convertir la columna monto_compras
    def clean_currency(value):
        if pd.isna(value):
            return 0.0
        if isinstance(value, str):
            # Quitar el símbolo de peso, espacios y reemplazar la coma por punto
            clean_val = value.replace('$', '').replace(' ', '').replace(',', '.')
            try:
                return float(clean_val)
            except ValueError:
                return 0.0
        return float(value)

    # Aplicar la conversión
    df['monto_compras_numeric'] = df['monto_compras'].apply(clean_currency)

    # Calcular la suma total
    total_sum = df['monto_compras_numeric'].sum()

    # Retornar el resultado redondeado a 2 decimales
    return round(float(total_sum), 2)
